def transform(grid):
    out = [row[:] for row in grid]
    vals = {v for row in grid for v in row}
    bg = max(vals, key=lambda v: sum(r.count(v) for r in grid))
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != bg]
        if not cols or cols[-1] == len(row) - 1:
            continue
        # A single uninterrupted foreground segment with a trailing gap is
        # extended in color 1; rows with internal holes are not.
        if len(cols) == cols[-1] - cols[0] + 1:
            for c in range(cols[-1] + 1, len(row)):
                out[r][c] = 1
    return out

